const CACHE='naiwa-island-v21-20261024-settlement';
const FILES=['./','./index.html','./style.css?v=17','./app.js?v=16','./audio.js','./preferences.js','./audio/naiwa-laugh-excerpt.mp3','./fonts/NaiwaUI.woff2','./fonts/OFL.txt','./share.js','./setup.js','./advanced-panel.js','./businesses.js','./business-panel.js','./cards-panel.js','./results-panel.js','./content.js','./engine.js?v=16','./maps.js','./portfolio.js','./difficulty.js','./stocks-panel.js','./talents.js?v=16','./orientation.js','./new-characters.js','./strategy.js','./pacing.js','./illustrations.js','./faces.js','./scene.js','./map-gestures.js','./minimap.js','./navigation.js','./characters.js','./naigou.js','./sculpt.js','./reference-characters.js','./island.js','./news.js','./buildings.js','./render-kit.js','./effects.js','./portraits.js','./icon.svg','./vendor/three.module.js','./vendor/three.core.js'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('naiwa-island-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request,{cache:'no-cache'}).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
